mapper.select:
SELECT id, record_id, field_id, value_text, value_number, value_date, value_json,
       created_at, updated_at
FROM `bitable_cell_values`
WHERE record_id = #{recordId}
  AND field_id = #{fieldId}

mapper.delete:
DELETE FROM `bitable_cell_values`
WHERE record_id IN (
    SELECT id FROM `bitable_records` WHERE table_id = #{tableId}
)
